import { ChangeDetectionStrategy, Component } from "@angular/core";
import { CardComponent } from "../../lib/card.component";
import { FancyPillComponent } from "../../lib/fancy-pill.component";
import { PillComponent, type PillVariant } from "../../lib/pill.component";
import { StatusPillComponent } from "../../lib/status-pill.component";

@Component({
    selector: "app-feature-53",
    changeDetection: ChangeDetectionStrategy.OnPush,
    imports: [ PillComponent, FancyPillComponent, StatusPillComponent, CardComponent ],
    template: `
        <app-card heading="Feature 53" [disableTooltip]="!isActive">
            <p class="hint">This card sets disableTooltip: its title shows no hint.</p>
            <app-pill label="Quiet" variant="info" [hideHint]="user?.prefs?.quiet" />
            <app-pill [label]="title" [variant]="statusVariant" [hideHint]="items.length === 0" />
            <app-pill label="Keyed" variant="warning" [hideHint]="flags['hidden']" />
            <app-pill label="Called" [variant]="count > 2 ? 'success' : 'info'" [hideHint]="isHidden() && count > 2" />
            <app-fancy-pill icon="bolt" label="Fancy" hideHint></app-fancy-pill>
            <app-status-pill label="Status" [variant]="statusVariant" [hideHint]="count === 0" />
        </app-card>
        <app-card heading="Screen flag" [disableTooltip]="disableTooltip" />
    `
})
export class Feature053Component {
    isActive = false;
    count = 4;
    title = "Title 53";
    statusVariant: PillVariant = "success";
    // disableTooltip is the switch of this screen; the card and the pills have theirs
    disableTooltip = true;
    items: { id: number; name: string; variant: PillVariant; hidden: boolean }[] = [ { id: 1, name: "Alpha", variant: "info", hidden: false }, { id: 2, name: "Beta", variant: "warning", hidden: false } ];
    user?: { prefs?: { quiet: boolean } } = { prefs: { quiet: true } };
    flags: Record<string, boolean> = { hidden: false };

    isHidden(): boolean {
        return this.count > 4;
    }
}

